                            currentByteIndex = idx + 1;
                            currentByteOffset = off + 1;
                            return FIT_FALSE;
                        }
                    }
                    else if ( decodeReturn == RETURN_END_OF_FILE )
                    {
                        currentByteIndex = idx + 1;
                        currentByteOffset = off + 1;
                        return FIT_TRUE;
                    }
